// is with type args — illegal
// if (x is List<String>) { }   // ERROR: cannot check for instanceof parameterized type

// unchecked cast defers failure to first read
val s = x as List<String>      // compiles with warning
s[0].uppercase()               // ClassCastException here, not at the cast

// the anonymous-subclass trick
val token = object : TypeToken<List<User>>() {}   // Signature attribute preserved

// typeOf recovers the parameterized type via Kotlin metadata
val t: KType = typeOf<List<User>>()

// arrays: reified + covariant
val a: Array<String> = arrayOf("x")
val o: Array<Any> = a          // compiles (covariance)
o[0] = 1                       // ArrayStoreException at runtime

inline fun <reified T> fromJson(json: String): T =
    decode(json, typeOf<T>())        // typeOf keeps List<User> intact

// Cannot be: open, in an interface, or forwarded to non-inline generic
// open inline fun <reified T> f() {}   // ERROR

// No T() — pass a factory instead
inline fun <reified T> create(factory: () -> T): T = factory()

// T::class loses type arguments; typeOf preserves them
// T = List<User>  ->  T::class == List; typeOf<T>() == List<User>

fun <T> f(x: T) = x
f<String?>(null)          // compiles — T's bound is Any?

fun <T : Any> g(x: T) = x
// g(null)                  // ERROR: Type argument is not within its bounds

fun <T> h(x: T) where T : Comparable<T>, T : Serializable = x

interface Builder<T : Builder<T>> { fun build(): String }   // self type

// Java:  void register(@NotNull K key, V value)
override fun register(key: K, value: V & Any) { }

interface Producer<out T> { fun produce(): T }   // out — T only leaves
interface Consumer<in T> { fun accept(v: T) }      // in — T only enters

class MutableBox<T> { var value: T }               // invariant — reads AND writes

// List<out E> yet contains(E): the UnsafeVariance exception
interface List<out E> {
    fun contains(element: @UnsafeVariance E): Boolean   // read-only use
}

// emptyList(): List<Nothing> — assignable to List<T>
val anyList: List<String> = emptyList()

// use-site projection, when variance is call-specific
fun <T> combineInto(dst: MutableList<in T>, src: List<out T>)
